import { SvgXml } from "react-native-svg";

import { illustrations, type IllustrationName } from "@/data/illustrations";
import { useTheme } from "@/hooks/useTheme";

type IllustrationProps = {
  name: IllustrationName;
  width: number;
  height: number;
};

// Renders the light or dark variant generated by scripts/generate-illustrations.js.
export function Illustration({ name, width, height }: IllustrationProps) {
  const { scheme } = useTheme();

  return <SvgXml xml={illustrations[name][scheme]} width={width} height={height} />;
}
